    int a[8];
    for (std::size_t i = 0; i != std::size(a); ++i) {
        for (std::size_t j = 0; j != i; ++j) {
            a[j] = 0;
        }
        for (;;) {
            binaryurp::Cache< int > c(4);
            for (std::size_t k = 0; k != i; ++k) {
                bool f;
                c.add(a[k], &f);
            }
            bool f;
            CPPUNIT_ASSERT_EQUAL(
                6,
                c.add(-1, &f) + c.add(-2, &f) + c.add(-3, &f) + c.add(-4, &f));
            std::size_t j = i;
            while (j != 0 && a[j - 1] == 3) {
                --j;
            }
            if (j == 0) {
                break;
            }
            ++a[j - 1];
            for (std::size_t k = j; k != i; ++k) {
                a[k] = 0;
            }
        }
    }
